{"implementation":"from fractions import Fraction
import math


def _require_int(value, field):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{field} must be an integer")
    return value


def _require_importance(value, field):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{field} must be a finite number")
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError(f"{field} must be finite")
        return Fraction(str(value))
    return Fraction(value)


def solve(case):
    if not isinstance(case, dict):
        raise TypeError("case must be an object")
    if "segments" not in case:
        raise ValueError("missing required field: segments")
    if "budget" not in case:
        raise ValueError("missing required field: budget")

    segments = case["segments"]
    if not isinstance(segments, list):
        raise TypeError("segments must be an array")
    budget = _require_int(case["budget"], "budget")

    names = []
    importances = []
    allocations = []
    capacities = []
    seen_names = set()

    for index, segment in enumerate(segments):
        prefix = f"segments[{index}]"
        if not isinstance(segment, dict):
            raise TypeError(f"{prefix} must be an object")
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in segment:
                raise ValueError(f"missing required field: {prefix}.{field}")

        name = segment["name"]
        if not isinstance(name, str):
            raise TypeError(f"{prefix}.name must be a string")
        if name in seen_names:
            raise ValueError(f"duplicate segment name: {name}")
        seen_names.add(name)

        importance = _require_importance(segment["importance"], f"{prefix}.importance")
        minimum = _require_int(segment["minimum"], f"{prefix}.minimum")
        capacity = _require_int(segment["capacity"], f"{prefix}.capacity")
        if minimum < 0:
            raise ValueError(f"{prefix}.minimum must be nonnegative")
        if capacity < minimum:
            raise ValueError(f"{prefix}.capacity must be at least its minimum")

        names.append(name)
        importances.append(importance)
        allocations.append(minimum)
        capacities.append(capacity)

    minimum_total = sum(allocations)
    capacity_total = sum(capacities)
    if budget < minimum_total:
        raise ValueError("budget is below the total minimum quota")
    if budget > capacity_total:
        raise ValueError("budget exceeds total capacity")

    remaining = budget - minimum_total
    while remaining:
        best_index = None
        best_priority = None
        for index in range(len(segments)):
            if allocations[index] >= capacities[index]:
                continue
            priority = importances[index] / (allocations[index] + 1)
            if best_index is None or priority > best_priority:
                best_index = index
                best_priority = priority
        allocations[best_index] += 1
        remaining -= 1

    return {
        "allocations": allocations,
        "by_name": {name: allocations[index] for index, name in enumerate(names)},
        "total": sum(allocations),
    }
"}
